(function(){'use strict';var SUPPORTED_LANGS=['fr','en','nl','de','it'];var DEFAULT_LANG='fr';var STORAGE_KEY='chalet_lang_pref';var LANG_NAMES={fr:{en:'anglais',nl:'n\u00e9erlandais',de:'allemand',it:'italien',fr:'fran\u00e7ais'},en:{fr:'French',nl:'Dutch',de:'German',it:'Italian',en:'English'},nl:{fr:'Frans',en:'Engels',de:'Duits',it:'Italiaans',nl:'Nederlands'},de:{fr:'Franz\u00f6sisch',en:'Englisch',nl:'Niederl\u00e4ndisch',it:'Italienisch',de:'Deutsch'},it:{fr:'francese',en:'inglese',nl:'olandese',de:'tedesco',it:'italiano'}};function getCurrentLang(){var path=window.location.pathname;for(var i=0;i<SUPPORTED_LANGS.length;i++){if(path.indexOf('/'+SUPPORTED_LANGS[i]+'/')===0){return SUPPORTED_LANGS[i];}}
return DEFAULT_LANG;}
function detectBrowserLang(){var navLang=(navigator.language||navigator.userLanguage||'').toLowerCase();var primary=navLang.split('-')[0];if(SUPPORTED_LANGS.indexOf(primary)!==-1){return primary;}
return DEFAULT_LANG;}
function getLangUrl(lang){if(lang===DEFAULT_LANG){return'/';}
return'/'+lang+'/';}
function showLanguageSuggestion(){if(localStorage.getItem(STORAGE_KEY)){return;}
var currentLang=getCurrentLang();var browserLang=detectBrowserLang();if(browserLang===currentLang){localStorage.setItem(STORAGE_KEY,currentLang);return;}
var banner=document.getElementById('langSuggestion');if(!banner){return;}
var langName=(LANG_NAMES[currentLang]&&LANG_NAMES[currentLang][browserLang])||browserLang;var textEl=banner.querySelector('.lang-suggestion-text');if(textEl){textEl.textContent=textEl.textContent.replace(/\{lang\}/g,langName);}
var switchBtn=document.getElementById('langSwitchBtn');if(switchBtn){switchBtn.textContent=switchBtn.textContent.replace(/\{lang\}/g,langName);switchBtn.href=getLangUrl(browserLang);switchBtn.addEventListener('click',function(){localStorage.setItem(STORAGE_KEY,browserLang);});}
var stayBtn=document.getElementById('langStayBtn');if(stayBtn){stayBtn.addEventListener('click',function(){localStorage.setItem(STORAGE_KEY,currentLang);banner.style.display='none';});}
banner.style.display='';}
function highlightActiveLang(){var currentLang=getCurrentLang();var items=document.querySelectorAll('#langSwitcher .dropdown-item');for(var i=0;i<items.length;i++){var itemLang=items[i].getAttribute('data-lang');if(itemLang===currentLang){items[i].classList.add('active');}else{items[i].classList.remove('active');}}}
function setupSwitcher(){var items=document.querySelectorAll('#langSwitcher .dropdown-item');for(var i=0;i<items.length;i++){items[i].addEventListener('click',function(e){var lang=this.getAttribute('data-lang');localStorage.setItem(STORAGE_KEY,lang);});}}
document.addEventListener('DOMContentLoaded',function(){highlightActiveLang();setupSwitcher();showLanguageSuggestion();});})();
(function(){var STORAGE_KEY='chalet_cookie_consent';var EXPIRY_DAYS=180;function getConsent(){try{var data=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!data||!data.timestamp)return null;var age=Date.now()-data.timestamp;if(age>EXPIRY_DAYS*24*60*60*1000){localStorage.removeItem(STORAGE_KEY);return null;}
return data.accepted;}catch(e){return null;}}
function setConsent(accepted){localStorage.setItem(STORAGE_KEY,JSON.stringify({accepted:accepted,timestamp:Date.now()}));if(accepted){loadGTM();}
hideBanner();}
function loadGTM(){var gtmMeta=document.querySelector('meta[name="gtm-id"]');var gtmId=gtmMeta?gtmMeta.getAttribute('content'):'';if(!gtmId||window._gtmLoaded)return;window._gtmLoaded=true;window.dataLayer=window.dataLayer||[];window.dataLayer.push({'gtm.start':new Date().getTime(),event:'gtm.js'});var s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtm.js?id='+gtmId;document.head.appendChild(s);}
function showBanner(){var banner=document.getElementById('cookieConsent');if(banner)banner.style.display='';}
function hideBanner(){var banner=document.getElementById('cookieConsent');if(banner)banner.style.display='none';}
function init(){var consent=getConsent();if(consent===true){loadGTM();return;}
if(consent===false){return;}
showBanner();var acceptBtn=document.getElementById('cookieAccept');var rejectBtn=document.getElementById('cookieReject');if(acceptBtn)acceptBtn.addEventListener('click',function(){setConsent(true);});if(rejectBtn)rejectBtn.addEventListener('click',function(){setConsent(false);});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
(function(){var input=document.getElementById('faqSearch');if(!input)return;var faqSection=document.getElementById('faq');var items=faqSection.querySelectorAll('.accordion-item');var categories=faqSection.querySelectorAll('.faq-category');input.addEventListener('input',function(){var q=this.value.toLowerCase().trim();items.forEach(function(item){var text=item.textContent.toLowerCase();item.style.display=(!q||text.indexOf(q)!==-1)?'':'none';});categories.forEach(function(cat){var accordion=cat.nextElementSibling;if(!accordion)return;var visible=accordion.querySelectorAll('.accordion-item:not([style*="display: none"])');cat.style.display=visible.length?'':'none';accordion.style.display=visible.length?'':'none';});});})();